{
  "name": "builder_all_pairs_gap_linear_tuned_002",
  "intuition": "Fine-tuned the pairwise gap linear weighting hyperparameters to improve stability and contrast in pair weights, reducing the clamping range from [0.25, 4.0] to [0.2, 3.0], thereby emphasizing more significant gaps while maintaining non-negativity and boundedness.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_linear",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "gap_linear"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "obj_z",
      "rank",
      "regret"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})\n    eps = 1e-6\n    raw = gap.clamp_min(0.0)\n    clamp_lo = float(extra.get('gap_lower_threshold', 0.2))\n    clamp_hi = float(extra.get('gap_upper_threshold', 3.0))\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})"
}

