  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})\n    eps = 1e-6\n    raw = gap.clamp_min(0.0)\n    clamp_lo = 0.35\n    clamp_hi = 3.0\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    # Apply sigmoid to smooth weights and prevent abrupt cutoffs\n    weight = torch.sigmoid(weight * 4.0 - 2.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})\n"
}

{
  "name": "all_pairs_gap_sigmoid_simple",
  "intuition": "Vectorized all_pairs builder using gap differences with simplified stable sigmoid weighting and clamping to produce soft weights preserving pair order and weight_family gap_sigmoid.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_sigmoid",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "sigmoid",
    "clamp",
    "nonzero"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    objective = feature_cache['objective']\n    # Compute all pairs where first obj < second obj\n    mask = (objective[:, :, None] < objective[:, None, :])\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})\n    # Gap is positive: loser_obj - winner_obj > 0\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap = gap.clamp_min(0.0)\n    # Clamp gap linearly, then apply sigmoid to produce soft bounded weights\n    clamp_lo = 0.5\n    clamp_hi = 2.5\n    gap_clamped = gap.clamp(clamp_lo, clamp_hi)\n    weight = torch.sigmoid(4.0 * gap_clamped - 3.0)  # shifted sigmoid for smoothness\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})"
}

{
  "name": "pairwise_weight_histogram_003",
  "intuition": "This crossover combines the linear gap weighting from parent 1 with the sigmoid-based normalization and clamp strategies from parent 0, enhancing the weighting nonlinearity while maintaining the stable pair topology. It introduces a sigmoid transform to smoothly scale the raw gap-based weights, and applies a monotonic clamp to ensure weights stay within a desired range, leveraging the strengths of both parent ideas for a more robust and configurable weight function.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_sigmoid",
    "constraint_family": "clamp_only"
  },
  "operators_used": ["all_pairs", "sigmoid", "clamp", "mul", "add"],
  "implementation_hint": {
    "expects": ["objective", "log_prob", "obj_z", "rank", "regret"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Reuse pair indices as in fixed topology\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Calculate raw gap weights\n    raw_weight = gap.clamp_min(0.0)\n    # Apply sigmoid transform for nonlinearity\n    sigmoid_weight = ops.sigmoid(raw_weight)\n    # Clamp for stability\n    clamped_weight = ops.clamp(sigmoid_weight, 0.25, 4.0)\n    # Return PrefBatch with updated weight\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=clamped_weight, meta={'builder': 'weighted_sigmoid', 'weight_family': 'gap_sigmoid'})"
}

