{
  "name": "builder_all_pairs_gap_softmax_005",
  "intuition": "rule_based:all_pairs:reweight:gap_softmax - uses a smooth softmax weighting of pair gaps to focus on relatively larger gaps while preserving all pairs",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_softmax",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "softmax"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "obj_z",
      "rank",
      "regret"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = b_idx.numel()\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_softmax'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_clamped = gap.clamp_min(0.0)\n    beta = float(extra.get('weight_beta', 1.0))\n    # Compute softmax weights over gaps per batch instance separately\n    # For numerical stability, subtract max gap per batch instance before exp\n    max_gap_per_instance = torch.zeros(objective.size(0), device=gap.device) - float('inf')\n    max_gap_per_instance.scatter_reduce_(0, b_idx, gap_clamped, reduce='amax', include_self=True)\n    gap_max = max_gap_per_instance[b_idx]\n    exp_gap = (beta * (gap_clamped - gap_max)).exp()\n    # Sum exp over pairs within each batch\n    sum_exp_per_instance = torch.zeros(objective.size(0), device=gap.device)\n    sum_exp_per_instance.scatter_add_(0, b_idx, exp_gap)\n    weight_raw = exp_gap / sum_exp_per_instance[b_idx]\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    weight = weight_raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_softmax'})\n"
}

