  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    objective = feature_cache['objective']\n    # all pairs mask where loser has strictly greater objective than winner\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = b_idx.numel()\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Clamp gap at 0 (should be already > 0) then apply sigmoid weighting\n    # Parameter for sigmoid steepness\n    beta = float(extra.get('weight_beta', 5.0))\n    x = beta * (gap - 0.5)\n    raw = torch.sigmoid(x)\n    # Clamp weights to reasonable bounds to avoid vanishing or exploding\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})\n"
}

