{
  "name": "builder_all_pairs_gap_sigmoid_thresholded_001",
  "intuition": "Apply a sigmoid smoothing to the positive gap values, emphasizing mid-range gaps while suppressing near-zero ties, preserving all-pairs topology and explicit clamping.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_sigmoid",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "clamp",
    "sigmoid",
    "sub",
    "mul"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_pos = gap.clamp(min=0.0)\n    tau = float(extra.get('weight_tau', 8.0))\n    threshold = float(extra.get('threshold', 0.2))\n    shifted_gap = gap_pos - threshold\n    sigmoid_weights = 1.0 / (1.0 + (-shifted_gap * tau).exp())\n    # Zero weight for gaps below threshold,\n    zero_mask = (gap_pos < threshold).to(dtype=sigmoid_weights.dtype)\n    weight_raw = sigmoid_weights * (1.0 - zero_mask)\n    clamp_lo = float(extra.get('clamp_lo', 0.1))\n    clamp_hi = float(extra.get('clamp_hi', 4.0))\n    weight = weight_raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})"
}

